from app import store


def get_customer(customer_id):
    return store.CUSTOMERS[customer_id]


def list_customers():
    return sorted(store.CUSTOMERS.values(), key=lambda c: c["id"])


class CustomerHasInvoicesError(Exception):
    """Raised when deleting a customer that invoices still refer to."""


def delete_customer(customer_id):
    """Remove a customer.

    Raises KeyError if there is no such customer, and
    CustomerHasInvoicesError if any invoice still points at them, so a
    delete never leaves invoices without a customer.
    """
    if customer_id not in store.CUSTOMERS:
        raise KeyError(customer_id)
    invoice_ids = [
        invoice["id"]
        for invoice in store.INVOICES
        if invoice["customer_id"] == customer_id
    ]
    if invoice_ids:
        raise CustomerHasInvoicesError(
            f"customer {customer_id} still has invoices: {invoice_ids}"
        )
    del store.CUSTOMERS[customer_id]

