from app import index
from app.limits import Limiter

_limiter = Limiter(per_minute=120)


def _caller(request):
    """Identify who is calling, by the broadest identity the request carries.

    Account first, so an integration cannot get a fresh budget by rotating
    API keys; IP only for requests with no credentials at all.
    """
    if request.account_id is not None:
        return ("account", request.account_id)
    if request.api_key is not None:
        return ("key", request.api_key)
    return ("ip", request.ip)


def handle(request):
    if not _limiter.allow(_caller(request)):
        return {"status": 429, "hits": []}
    return {"status": 200, "hits": index.search(request.query)}

