    return {"status": 200, "hits": index.search(request.query)}

from app import index
from app.limits import Limiter

# Per-caller budget. Search scans the whole index on every call, so this is
# what stops one caller from starving the rest.
SEARCHES_PER_MINUTE = 120

_limiter = Limiter(per_minute=SEARCHES_PER_MINUTE)


def _caller(request):
    """Identify who to charge the request to.

    Prefer the account, so an integration cannot multiply its budget by
    spreading load over several API keys or IPs. Fall back to the key and then
    the IP so that requests without an account do not all share one bucket.
    """
    if request.account_id is not None:
        return ("account", request.account_id)
    if request.api_key is not None:
        return ("api_key", request.api_key)
    return ("ip", request.ip)


def handle(request):
    if not _limiter.allow(_caller(request)):
        return {"status": 429, "hits": []}
    return {"status": 200, "hits": index.search(request.query)}

