from app import gateway, queue

RECONCILE_QUEUE = "payment-reconcile"


def pay(account_id, cents):
    try:
        receipt = gateway.charge(account_id, cents)
    except gateway.GatewayTimeout:
        # A timeout does not tell us whether the card was charged, and
        # gateway.charge() has no idempotency key, so charging again here
        # could bill the customer twice. Report the outcome as unknown and
        # hand it off to be settled out of band.
        queue.enqueue(RECONCILE_QUEUE, {"account_id": account_id, "cents": cents})
        return {"status": "pending", "receipt": None}
    return {"status": "paid", "receipt": receipt}

